def compare_ages(my_age, your_age):
    diff = my_age - your_age
    if diff == 0:
        return "We are the same age."
    elif diff > 0:
        unit = "year" if diff == 1 else "years"
        return f"I am {diff} {unit} older than you."
    else:
        diff = abs(diff)
        unit = "year" if diff == 1 else "years"
        return f"You are {diff} {unit} older than me."
